<?php require_once __DIR__.'/../src/Finance.php';$cases=[['principal'=>1000000,'rate'=>.05,'term'=>5,'interest'=>50000,'capital'=>1000000,'total'=>1250000],['principal'=>900,'rate'=>0,'term'=>3,'interest'=>0,'capital'=>900,'total'=>900]];$fail=0;foreach($cases as $c){$rows=Finance::amortization($c['principal'],$c['rate'],$c['term'],new DateTimeImmutable('2026-01-15'));$capital=array_sum(array_column($rows,'principal'));$interest=array_sum(array_column($rows,'interest'));$total=array_sum(array_column($rows,'total'));if(count($rows)!==$c['term']||$capital!=$c['capital']||$interest!=$c['interest']*$c['term']||$total!=$c['total']){$fail++;echo "FAIL parity\n";}else echo "PASS parity principal={$c['principal']} term={$c['term']}\n";}exit($fail?1:0);
